<?php get_header(); ?><main class="wrap" id="main"><div class="intro"><p class="eyebrow">TodayUK / CR News</p><h1><?php if(is_search()){echo 'Search: '.esc_html(get_search_query());}elseif(is_archive()){echo esc_html(get_the_archive_title());}else{echo 'Latest stories';} ?></h1><?php if(is_category()): ?><p><?php echo wp_kses_post(category_description()); ?></p><?php endif; ?></div><?php if(have_posts()): ?><div class="cards"><?php while(have_posts()):the_post();todayuk_card();endwhile; ?></div><div class="pagination"><?php the_posts_pagination(['prev_text'=>'← Newer','next_text'=>'Older →']); ?></div><?php else: ?><div class="empty"><h2><?php echo is_search()?'No matching stories':'Coverage is on its way'; ?></h2><p><?php echo is_search()?'Try a different search or explore the sections above.':'Stories will appear here once they have been reviewed and published.'; ?></p><a class="button" href="<?php echo esc_url(home_url('/')); ?>">Back to TodayUK</a></div><?php endif; ?></main><?php get_footer(); ?>
